import 'package:flutter/material.dart';import '../core/utils/formatters.dart';import '../data/repositories/expense_repository.dart';
class GoalsScreen extends StatefulWidget{const GoalsScreen({super.key});@override State<GoalsScreen> createState()=>_GoalsScreenState();}
class _GoalsScreenState extends State<GoalsScreen>{final repo=ExpenseRepository();late Future<List<Map<String,Object?>>> future;@override void initState(){super.initState();future=repo.goals();}void reload()=>setState(()=>future=repo.goals());
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Savings goals')),body:FutureBuilder<List<Map<String,Object?>>>(future:future,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const Center(child:Text('Create a goal and start saving towards it.'));return ListView(padding:const EdgeInsets.all(16),children:s.data!.map((e){final target=e['target_minor'] as int,saved=e['saved_minor'] as int,ratio=target==0?0.0:(saved/target).clamp(0,1).toDouble();return Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(e['name'] as String,style:const TextStyle(fontWeight:FontWeight.w800,fontSize:17)),const SizedBox(height:8),LinearProgressIndicator(value:ratio,minHeight:8),const SizedBox(height:8),Row(children:[Expanded(child:Text(Fmt.money(saved/100)+' saved')),Text('of '+Fmt.money(target/100))]),Align(alignment:Alignment.centerRight,child:TextButton.icon(onPressed:()=>contribute(e['id'] as int),icon:const Icon(Icons.add),label:const Text('Add savings')))])));}).toList());}),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('New goal')));
 Future<void> add()async{final name=TextEditingController(),amount=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Create savings goal'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Goal name')),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Target amount',prefixText:'₹ '))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),TextButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))]));final n=double.tryParse(amount.text);if(ok==true&&name.text.trim().isNotEmpty&&n!=null&&n>0){await repo.addGoal(name.text.trim(),(n*100).round());reload();}name.dispose();amount.dispose();}
 Future<void> contribute(int id)async{final amount=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Add to savings'),content:TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(prefixText:'₹ ',labelText:'Amount')),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),TextButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Add'))]));final n=double.tryParse(amount.text);if(ok==true&&n!=null&&n>0){await repo.contributeGoal(id,(n*100).round());reload();}amount.dispose();}
}
